import chess

board = chess.Board('r1bqkb1r/pppp1ppp/3n4/4n3/8/8/PPPP1PPP/RNBQRBK1 b kq - 1 7')
print('White material:', board.occupied_co[chess.WHITE])
print('Black material:', board.occupied_co[chess.BLACK])
print('White pieces:', [chess.square_name(sq) + ':' + chess.piece_name(board.piece_at(sq).piece_type) for sq in chess.SQUARES if board.color_at(sq) == chess.WHITE])
print('Black pieces:', [chess.square_name(sq) + ':' + chess.piece_name(board.piece_at(sq).piece_type) for sq in chess.SQUARES if board.color_at(sq) == chess.BLACK])

# Count material by piece type
white_counts = {}
black_counts = {}
for sq in chess.SQUARES:
    piece = board.piece_at(sq)
    if piece:
        if piece.color == chess.WHITE:
            white_counts[piece.piece_type] = white_counts.get(piece.piece_type, 0) + 1
        else:
            black_counts[piece.piece_type] = black_counts.get(piece.piece_type, 0) + 1

print('White counts:', white_counts)
print('Black counts:', black_counts)
""}

